-- ═══ STEP 1: Delete SEO content for old Software & SaaS L2/L3 ═══
DELETE FROM category_seo_content
WHERE category_id IN (
  SELECT id FROM (
    SELECT id FROM categories
    WHERE parent_id IN (
      SELECT id FROM categories WHERE parent_id = (
        SELECT id FROM categories WHERE slug = 'software-saas' AND level = 1
      )
    )
    UNION
    SELECT id FROM categories
    WHERE parent_id = (
      SELECT id FROM categories WHERE slug = 'software-saas' AND level = 1
    )
  ) AS ids
);

-- ═══ STEP 2: Nullify submission category_id (preserve listings) ═══
UPDATE submissions SET category_id = NULL
WHERE category_id IN (
  SELECT id FROM (
    SELECT id FROM categories
    WHERE parent_id IN (
      SELECT id FROM categories WHERE parent_id = (
        SELECT id FROM categories WHERE slug = 'software-saas' AND level = 1
      )
    )
    UNION
    SELECT id FROM categories
    WHERE parent_id = (
      SELECT id FROM categories WHERE slug = 'software-saas' AND level = 1
    )
  ) AS ids
);

-- ═══ STEP 3: Delete listing types for old Software & SaaS L3s ═══
DELETE FROM listing_types
WHERE category_id IN (
  SELECT id FROM (
    SELECT id FROM categories
    WHERE parent_id IN (
      SELECT id FROM categories WHERE parent_id = (
        SELECT id FROM categories WHERE slug = 'software-saas' AND level = 1
      )
    )
  ) AS ids
);

-- ═══ STEP 4: Delete old L3 categories ═══
DELETE FROM categories
WHERE level = 3 AND parent_id IN (
  SELECT id FROM (
    SELECT id FROM categories WHERE parent_id = (
      SELECT id FROM categories WHERE slug = 'software-saas' AND level = 1
    )
  ) AS ids
);

-- ═══ STEP 5: Delete old L2 categories ═══
DELETE FROM categories
WHERE level = 2 AND parent_id = (
  SELECT id FROM (
    SELECT id FROM categories WHERE slug = 'software-saas' AND level = 1
  ) AS t1
);

